/* @lc app=leetcode id=1993 lang=kotlin */ class LockingTree(val parent: IntArray, val owner: IntArray = IntArray(parent.size), val ch: List<List<Int>> = parent.indices.groupBy { parent[it] }.let { g -> parent.indices.map { g[it].orEmpty() } }) { fun lock(num: Int, user: Int): Boolean = owner[num] == 0 && true.also { owner[num] = user } fun unlock(num: Int, user: Int): Boolean = owner[num] == user && true.also { owner[num] = 0 } fun upgrade(num: Int, user: Int): Boolean = owner[num] == 0 && !generateSequence(parent[num]) { parent[it] }.takeWhile { it >= 0 }.any { owner[it] != 0 } && generateSequence(ch[num]) { f -> f.flatMap { ch[it] }.takeIf { it.isNotEmpty() } }.flatten().filter { owner[it] != 0 }.toList().let { l -> l.isNotEmpty() && true.also { l.forEach { owner[it] = 0 } }.also { owner[num] = user } } }